// Strip signatures, legal footers and obvious noise before the LLM sees the text.
// Quoted threads are KEPT on purpose: real confirmations often live inside them.
const raw = $json['Email body'] || '';
const reviewer = $json['Reviewer name'] || 'demo user';

const cutMarkers = [
  /^--\s*$/m,
  /Este mensaje y sus adjuntos/i,
  /This message and its attachments/i,
  /aviso legal/i
];

let text = raw.replace(/\r\n/g, '\n');
for (const marker of cutMarkers) {
  const m = text.match(marker);
  if (m && m.index > 40) text = text.slice(0, m.index);
}

text = text
  .split('\n')
  .filter(l => !/^\s*(tel\.?|m[oó]vil|www\.|https?:\/\/)/i.test(l))
  .join('\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return [{ json: { cleanText: text, originalText: raw, reviewer, startedAt: new Date().toISOString() } }];

// Builds the request body. Two things happen here that matter in production:
// 1. limpia() neutralises control tags, so an email cannot impersonate the prompt.
// 2. json_schema forces the shape of the answer instead of hoping for valid JSON.
const cfg = $json;
const src = $('Normalize text').first().json;

const limpia = (s) => String(s || '')
  .replace(/<\s*\/?\s*(input|seguridad|reglas|rol|prompt_config|system)\b[^>]*>/gi, '[tag]');

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['is_order', 'customer_hint', 'requested_delivery', 'logistics_notes', 'not_order_reason', 'lines'],
  properties: {
    is_order: { type: 'boolean' },
    customer_hint: { type: 'string' },
    requested_delivery: { type: 'string' },
    logistics_notes: { type: 'string' },
    not_order_reason: { type: 'string' },
    lines: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['raw_text', 'reference', 'description', 'quantity', 'unit'],
        properties: {
          raw_text: { type: 'string' },
          reference: { type: 'string' },
          description: { type: 'string' },
          quantity: { type: 'number' },
          unit: { type: 'string', enum: ['cajas', 'm2', 'sacos', 'kits', 'unidades', ''] }
        }
      }
    }
  }
};

const payload = {
  model: cfg.model,
  max_tokens: cfg.max_tokens,
  system: cfg.system_prompt,
  output_config: {
    effort: cfg.effort,
    format: { type: 'json_schema', schema: SCHEMA }
  },
  messages: [
    {
      role: 'user',
      content: '<input>\n' + limpia(src.cleanText) + '\n</input>'
    }
  ]
};

return [{ json: { ...src, payload } }];

// Validate the model output against the expected shape. A malformed answer is flagged,
// never silently accepted.
const prev = $('Normalize text').first().json;

const blocks = Array.isArray($json.content) ? $json.content : [];
const textBlock = blocks.find(b => b && b.type === 'text' && b.text);
const rawOut = textBlock ? textBlock.text : ($json.text || '');

let parsed = null;
let parseError = null;
try {
  const match = String(rawOut).match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : rawOut);
} catch (e) {
  parseError = e.message;
}

const problems = [];
if (!rawOut) problems.push('The model returned no text block. stop_reason: ' + ($json.stop_reason || 'unknown'));
else if (!parsed) problems.push('LLM did not return valid JSON: ' + parseError);
else {
  if (typeof parsed.is_order !== 'boolean') problems.push('is_order missing');
  if (parsed.is_order && !Array.isArray(parsed.lines)) problems.push('lines missing');
}

// Loud failure beats a green run with no data.
if (problems.length) {
  throw new Error('Extraction failed - ' + problems.join(' | '));
}

return [{ json: { ...prev, extraction: parsed, schemaProblems: problems, schemaOk: true } }];

