// "ERP" write. In the demo this is a CSV row; in production it is the ERP API or DB.
const gate = $json;
const ctx = $('Build order proposal').first().json;
const orderId = 'DEMO-' + String(Date.now()).slice(-6);

const rows = ctx.proposal.lines.map(l => ({
  order_id: orderId,
  customer: ctx.proposal.customer,
  reference: l.reference,
  product: l.product,
  quantity: l.quantity,
  unit: l.unit,
  line_total_eur: l.lineTotal,
  approved_by: ctx.reviewer,
  decision: gate.Decision
}));

return [{ json: { ...ctx, orderId, decision: gate.Decision, corrections: Number(gate['Lines corrected by hand'] || 0), reviewerNotes: gate['Corrections or rejection reason'] || '', erpRows: rows } }];

// Telemetry: this is what turns "it works" into a measured number.
const j = $json;
const ctx = $('Build order proposal').first().json;
const lines = ctx.proposal.lines;
const totalLines = lines.length;
const autoResolved = lines.filter(l => l.status === 'high').length;
const corrections = j.corrections ?? 0;
const cycleMs = new Date() - new Date(ctx.startedAt);

return [{ json: {
  order_id: j.orderId ?? null,
  decision: j.decision ?? 'rejected',
  total_lines: totalLines,
  auto_resolved_lines: autoResolved,
  flagged_lines: totalLines - autoResolved,
  human_corrections: corrections,
  first_pass_accuracy_pct: totalLines ? Number(((autoResolved - corrections) / totalLines * 100).toFixed(1)) : null,
  cycle_seconds: Number((cycleMs / 1000).toFixed(1)),
  reviewer: ctx.reviewer
} }];

// Rejected or not an order: logged with the reason, never silently dropped.
const j = $json;
const ctx = $('Match against catalog').first().json;
return [{ json: {
  outcome: ctx.isOrder ? 'rejected_by_human' : 'not_an_order',
  reason: ctx.isOrder ? (j['Corrections or rejection reason'] || 'no reason given') : (ctx.extraction?.not_order_reason || 'the email is not a purchase order'),
  originalText: ctx.originalText
} }];
